module.render:
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rawKind = String(args.kind || 'theorem').trim() || 'theorem';
// A kind written in another script (定理, 命題 …) is the heading word itself.
const latin = /^[A-Za-z][\w -]*$/.test(rawKind);
const kind = latin ? rawKind.toLowerCase() : rawKind;
const name = latin ? kind.charAt(0).toUpperCase() + kind.slice(1) : esc(kind);
const number = (args.number || '').trim();
const title = (args.title || '').trim();
const color = args.color || 'var(--accent-color)';
const head = latin
  ? `${name}${number ? ' ' + esc(number) : ''}${title ? ' (' + esc(title) + ')' : ''}.`
  : `${name}${number ? ' ' + esc(number) : ''}${title ? '（' + esc(title) + '）' : ''}`;
const body = (content || '').trim();
const italicArg = String(args.italic || 'auto').toLowerCase();
const italic = italicArg === 'true' ? true : italicArg === 'false' ? false : (latin && !/definition|example|remark/.test(kind));
const headArg = String(args.head || 'auto').toLowerCase();
const block = headArg === 'block' || (headArg !== 'inline' && /^\s*([-*+]\s|\d+[.)]\s|\\\[|\$\$|\||<|#|>)/.test(body));
const variant = { bar: 'bar', outline: 'outline', plain: 'plain' }[String(args.variant || 'bar').toLowerCase()] || 'bar';
const cls = `mdp-mod-theorem mdp-th-${italic ? 'italic' : 'plain'}${block ? ' mdp-th-blockhead' : ''}${variant !== 'bar' ? ' mdp-th-v-' + variant : ''}${latin ? '' : ' mdp-th-cjk'}`;
return `\n\n<div class="${cls}" style="--th-color:${color};"><span class="mdp-th-head">${head}</span> <div class="mdp-th-body">\n\n${body}\n\n</div></div>\n\n`;
